#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    char *str1 = argv[1];
    char *str2 = argv[2];
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    int dp[len1 + 1][len2 + 1];
    for (int i = 0; i <= len1; i++) {
        for (int j = 0; j <= len2; j++) {
            if (i == 0 && j == 0) {
                dp[i][j] = 1;
            } else if (i == 0) {
                dp[i][j] = (str2[j - 1] == '*') ? dp[i][j - 1] : 0;
            } else if (j == 0) {
                dp[i][j] = 0;
            } else if (str1[i - 1] == str2[j - 1] || str2[j - 1] == '?') {
                dp[i][j] = dp[i - 1][j - 1];
            } else if (str2[j - 1] == '*') {
                dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
            } else {
                dp[i][j] = 0;
            }
        }
    }
    if (dp[len1][len2]) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
